CREATE DATABASE IF NOT EXISTS vocabulary_jam CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE vocabulary_jam;
CREATE TABLE IF NOT EXISTS users (id CHAR(36) PRIMARY KEY, google_sub VARCHAR(255) UNIQUE, display_name VARCHAR(80) NOT NULL, email VARCHAR(255), avatar TEXT, total_xp INT NOT NULL DEFAULT 0, coins INT NOT NULL DEFAULT 0, wins INT NOT NULL DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, last_login TIMESTAMP NULL);
CREATE TABLE IF NOT EXISTS questions (id VARCHAR(80) PRIMARY KEY, question TEXT NOT NULL, options JSON NOT NULL, answer_index TINYINT NOT NULL, explanation TEXT, topic VARCHAR(100), difficulty VARCHAR(20), status VARCHAR(20) DEFAULT 'published', updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS matches (id CHAR(36) PRIMARY KEY, room_code VARCHAR(12), question_count INT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS match_players (match_id CHAR(36) NOT NULL, user_id CHAR(36) NOT NULL, score INT NOT NULL DEFAULT 0, rank_position INT, PRIMARY KEY(match_id,user_id), FOREIGN KEY(match_id) REFERENCES matches(id), FOREIGN KEY(user_id) REFERENCES users(id));
